import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import path from "node:path";
import { ENGINE, engineVersion } from "./io";

/**
 * The thin shell: the small set of generated files that make a deck a Next.js app. Templates live in
 * the engine, each with a "Generated by live-ish" header where the format has comments. A deck commits
 * its copies, plus `live-ish.shell.json`, which records the hash of what the engine last wrote. That
 * record is how `upgrade` tells a file the engine moved on from (safe to rewrite) from a file a person
 * edited (stop and say so), since after `pnpm up` both differ from the new template.
 */

export const HEADER = "Generated by live-ish";
export const MANIFEST = "live-ish.shell.json";
/** npm drops a file named `.gitignore` from a package, so the template goes without the dot. */
const RENAMED: Record<string, string> = { gitignore: ".gitignore" };

export const hashOf = (text: string | Buffer) => createHash("sha256").update(text).digest("hex").slice(0, 16);

export interface ShellFile {
  /** Path in the deck, with forward slashes. */
  target: string;
  body: string;
}

export function shellFiles(): ShellFile[] {
  const dir = path.join(ENGINE, "shell");
  return readdirSync(dir, { withFileTypes: true, recursive: true })
    .filter((e) => e.isFile() && !e.name.startsWith("."))
    .map((e) => {
      const abs = path.join(e.parentPath, e.name);
      const rel = path.relative(dir, abs).split(path.sep).join("/");
      return { target: RENAMED[rel] ?? rel, body: readFileSync(abs, "utf8") };
    })
    .sort((a, b) => a.target.localeCompare(b.target));
}

export interface ShellManifest {
  engine: string;
  files: Record<string, string>;
}

export function readManifest(root: string): ShellManifest | null {
  try {
    return JSON.parse(readFileSync(path.join(root, MANIFEST), "utf8")) as ShellManifest;
  } catch {
    return null;
  }
}

/** current: matches the installed engine. outdated: untouched, written by an older engine. */
export type ShellState = "current" | "outdated" | "edited" | "missing";

export interface ShellEntry {
  target: string;
  state: ShellState;
  /** The file no longer carries the header, which `doctor` calls out by name. */
  headerLost?: boolean;
}

export function shellStatus(root: string): ShellEntry[] {
  const manifest = readManifest(root);
  return shellFiles().map(({ target, body }) => {
    const file = path.join(root, target);
    if (!existsSync(file)) return { target, state: "missing" };
    const text = readFileSync(file, "utf8");
    const headerLost = body.includes(HEADER) && !text.includes(HEADER);
    if (text === body) return { target, state: "current" };
    if (manifest?.files[target] === hashOf(text)) return { target, state: "outdated" };
    return { target, state: "edited", ...(headerLost ? { headerLost } : {}) };
  });
}

/** Files under `app/` the templates do not name, split by whether they carry the header. */
export function strayFiles(root: string): { retired: string[]; foreign: string[] } {
  const known = new Set(shellFiles().map((f) => f.target));
  const dir = path.join(root, "app");
  const out = { retired: [] as string[], foreign: [] as string[] };
  if (!existsSync(dir)) return out;
  for (const e of readdirSync(dir, { withFileTypes: true, recursive: true })) {
    if (!e.isFile() || e.name === ".DS_Store") continue;
    const abs = path.join(e.parentPath, e.name);
    const rel = path.relative(root, abs).split(path.sep).join("/");
    if (known.has(rel)) continue;
    (readFileSync(abs, "utf8").includes(HEADER) ? out.retired : out.foreign).push(rel);
  }
  return { retired: out.retired.sort(), foreign: out.foreign.sort() };
}

/** Writes every template into the deck, drops retired files, and records what it wrote. */
export function writeShell(root: string): { written: string[]; removed: string[] } {
  const files = shellFiles();
  const written: string[] = [];
  for (const { target, body } of files) {
    const file = path.join(root, target);
    if (existsSync(file) && readFileSync(file, "utf8") === body) continue;
    mkdirSync(path.dirname(file), { recursive: true });
    writeFileSync(file, body);
    written.push(target);
  }
  const { retired } = strayFiles(root);
  for (const rel of retired) rmSync(path.join(root, rel));
  const manifest: ShellManifest = { engine: engineVersion(), files: Object.fromEntries(files.map((f) => [f.target, hashOf(f.body)])) };
  writeFileSync(path.join(root, MANIFEST), `${JSON.stringify(manifest, null, 2)}\n`);
  return { written, removed: retired };
}
